'use strict';
// Builds dist/gfpi_production_bundle.js from gfpi/production/*.js (isomorphic, no Node built-ins). Frozen-core requires (../canon, ../ledger,
// ../decisions, ../questionPlan) resolve to the already-loaded window.GFPI bundle, so the frozen bundle is NOT modified. `--check` verifies freshness.
const fs = require('fs');
const path = require('path');
const { sha256Hex } = require('../gfpi/canon');

const root = path.join(__dirname, '..');
const dir = path.join(root, 'gfpi', 'production');
const MODULES = ['prodLedger', 'catalog', 'profile', 'adaptive', 'readiness', 'common', 'models', 'graph', 'factory', 'conflicts', 'guardian', 'discovery', 'attachment', 'index'];
const out = path.join(root, 'dist', 'gfpi_production_bundle.js');
const FROZEN = ['canon', 'ledger', 'decisions', 'questionPlan'];

function render() {
  const sources = MODULES.map((m) => fs.readFileSync(path.join(dir, m + '.js'), 'utf8'));
  const present = fs.readdirSync(dir).filter((f) => /\.js$/.test(f)).map((f) => f.replace(/\.js$/, '')).sort();
  if (present.join() !== MODULES.slice().sort().join()) throw new Error('production module list out of sync with directory: ' + present.join());
  sources.forEach((s, i) => {
    const re = /require\(['"]([^'"]+)['"]\)/g; let m;
    while ((m = re.exec(s))) {
      const r = m[1];
      if (r.indexOf('./') === 0) { if (MODULES.indexOf(r.slice(2)) === -1) throw new Error(MODULES[i] + ' requires unknown local ' + r); }
      else if (r.indexOf('../') === 0) { if (FROZEN.indexOf(r.slice(3)) === -1) throw new Error(MODULES[i] + ' requires non-bundled frozen module ' + r); }
      else throw new Error(MODULES[i] + ' requires a non-local module ' + r);
    }
  });
  const hash = sha256Hex(sources.join('\n\u0000\n')).slice(0, 16);
  let body = '/* AUTO-GENERATED by tools/buildGfpiProductionBundle.js — DO NOT EDIT BY HAND.\n * Modules: ' + MODULES.join(', ') + '\n * GFPI_PRODUCTION_SOURCE_HASH=' + hash + '\n * Requires dist/gfpi_bundle.js (window.GFPI) to be loaded first.\n */\n(function (global) {\n  "use strict";\n  var F = global.GFPI; if (!F) throw new Error("GFPI bundle must load before the production bundle");\n  var defs = {}; var cache = {};\n  function req(name) {\n    if (name.indexOf("../") === 0) { var f = F[name.slice(3)]; if (!f) throw new Error("missing frozen module " + name); return f; }\n    name = name.replace(/^\\.\\//, ""); if (cache[name]) return cache[name].exports; var m = { exports: {} }; cache[name] = m; defs[name](m, m.exports, req); return m.exports;\n  }\n';
  MODULES.forEach((m, i) => { body += '  defs[' + JSON.stringify(m) + '] = function (module, exports, require) {\n' + sources[i] + '\n  };\n'; });
  body += '  var api = req("./index"); api.SOURCE_HASH = ' + JSON.stringify(hash) + ';\n  global.GFPI_PRODUCTION = api;\n})(typeof window !== "undefined" ? window : globalThis);\n';
  return { body, hash };
}

const r = render();
if (process.argv.includes('--check')) {
  const cur = fs.existsSync(out) ? fs.readFileSync(out, 'utf8') : '';
  if (cur !== r.body) { console.error('STALE dist/gfpi_production_bundle.js — run: node tools/buildGfpiProductionBundle.js'); process.exit(1); }
  console.log('gfpi production bundle fresh (' + r.hash + ')');
} else { fs.writeFileSync(out, r.body); console.log('gfpi production bundle written (' + r.hash + ')'); }
